eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   powerpointModule1Lessons: () => (/* binding */ powerpointModule1Lessons)\n/* harmony export */ });\nconst powerpointModule1Lessons = [\n    {\n        slug: \"getting-started-with-powerpoint\",\n        title: \"Getting Started with PowerPoint\",\n        description: \"Learn your way around the PowerPoint interface including the Ribbon, Quick Access Toolbar, slide views, zoom controls, and Backstage view.\",\n        duration: \"12 min\",\n        videoUrl: \"https://www.youtube.com/embed/k6pg4nZS6fA\",\n        practiceFiles: [],\n        sections: [\n            {\n                heading: \"PowerPoint Start Screen\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"When you open PowerPoint, the Start Screen appears. From here you can create a new presentation, choose from templates, or open recent files.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Select Blank Presentation to open the PowerPoint editing environment and begin building your slides.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_interface.png\",\n                        alt: \"PowerPoint interface overview\"\n                    }\n                ]\n            },\n            {\n                heading: \"Understanding the PowerPoint Interface\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Once a presentation opens, you will see the PowerPoint interface. The main workspace includes the Ribbon, slide navigation pane, slide editing area, and status bar.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The slide pane is where you build your presentation, while the navigation pane on the left allows you to organize and switch between slides.\"\n                    }\n                ]\n            },\n            {\n                heading: \"The Ribbon\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Ribbon contains the commands you use to create and edit presentations. It is organized into tabs such as Home, Insert, Design, Transitions, Animations, Slide Show, Review, and View.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Each tab contains groups of related commands. For example, the Font group contains tools for formatting text.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_ribbon.png\",\n                        alt: \"PowerPoint ribbon tabs\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_small_arrow.png\",\n                        alt: \"Ribbon dialog launcher\"\n                    }\n                ]\n            },\n            {\n                heading: \"Showing and Hiding the Ribbon\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can control how much of the Ribbon is visible using the Ribbon Display Options in the top-right corner of PowerPoint.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Options include Auto-hide Ribbon, Show Tabs, and Show Tabs and Commands.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_ribbon_dropdown.png\",\n                        alt: \"Ribbon display options\"\n                    }\n                ]\n            },\n            {\n                heading: \"Quick Access Toolbar\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Quick Access Toolbar is located above the Ribbon and provides quick access to commonly used commands such as Save, Undo, Redo, and Start From Beginning.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can customize the Quick Access Toolbar by clicking the drop-down arrow and selecting additional commands.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_quick_access.png\",\n                        alt: \"Quick access toolbar\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_quick_print_setup.png\",\n                        alt: \"Quick access customization menu\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_quick_print.png\",\n                        alt: \"Quick print added to quick access toolbar\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using the Tell Me Box\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Tell Me box works like a search tool inside PowerPoint. You can type the name of a command or feature and PowerPoint will help you find it instantly.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This is especially useful when you are learning PowerPoint and do not know where certain tools are located.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_shapes.png\",\n                        alt: \"Using the Tell Me box to search commands\"\n                    }\n                ]\n            },\n            {\n                heading: \"Ruler, Guides, and Gridlines\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint includes layout tools to help align objects on your slides. These include the ruler, guides, and gridlines.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can enable these tools from the View tab in the Ribbon under the Show group.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_view_tools.png\",\n                        alt: \"View tab ruler gridlines guides\"\n                    }\n                ]\n            },\n            {\n                heading: \"Slide Views\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint includes multiple slide views that change how your presentation is displayed. These include Normal view, Slide Sorter view, Reading view, and Slide Show view.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can switch between these views using the view buttons in the bottom-right corner of the PowerPoint window.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_slide_view_command.png\",\n                        alt: \"Slide view buttons\"\n                    }\n                ]\n            },\n            {\n                heading: \"Zoom Controls\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Zoom slider located in the bottom-right corner allows you to zoom in or out of your slide.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This helps you adjust your workspace when working on detailed slide content.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_zoom_command.png\",\n                        alt: \"Zoom slider control\"\n                    }\n                ]\n            },\n            {\n                heading: \"Backstage View\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Backstage view is accessed by clicking the File tab. It contains options for saving, printing, sharing, exporting, and managing your presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This area also shows presentation information such as file size, slide count, and document properties.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_file_tab.png\",\n                        alt: \"File tab backstage button\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/getting-started/powerpoint_backstage_view.png\",\n                        alt: \"PowerPoint backstage view\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open PowerPoint and create a blank presentation.\",\n                    \"Change the Ribbon Display Options to Show Tabs.\",\n                    \"Add New, Quick Print, and Spelling to the Quick Access Toolbar.\",\n                    \"Use the Tell Me box to search for Shapes.\",\n                    \"Insert a shape onto the slide.\",\n                    \"Enable the Ruler from the View tab.\",\n                    \"Zoom the presentation to 120%.\",\n                    \"Return the Ribbon display to Show Tabs and Commands.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-1/getting-started/powerpoint_final_result.png\",\n                alt: \"PowerPoint backstage view\"\n            }\n        ]\n    },\n    {\n        slug: \"understanding-onedrive-for-powerpoint\",\n        title: \"Understanding OneDrive for PowerPoint\",\n        description: \"Learn how to sign in to PowerPoint, connect your Microsoft account, and use OneDrive to save and access presentations from anywhere.\",\n        duration: \"8 min\",\n        sections: [\n            {\n                heading: \"What is OneDrive?\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"OneDrive is Microsoft's cloud storage service. It allows you to store presentations and other files online so you can access them from any computer, tablet, or smartphone with an internet connection.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Using OneDrive makes it easy to save, edit, and share PowerPoint presentations while keeping your files protected and backed up.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Signing in to PowerPoint\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"To use OneDrive features, you need to sign in with a Microsoft account. Click the Sign in button in the upper-right corner of the PowerPoint window.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"After signing in, PowerPoint connects to your OneDrive storage so you can save presentations online and access them across devices.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/onedrive/powerpoint_sign_in.png\",\n                        alt: \"PowerPoint sign in button\"\n                    }\n                ]\n            },\n            {\n                heading: \"Benefits of Using OneDrive\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Once you sign in, OneDrive provides several powerful advantages for managing presentations.\"\n                    },\n                    {\n                        type: \"list\",\n                        ordered: false,\n                        items: [\n                            \"Access files anywhere from any device connected to the internet.\",\n                            \"Back up presentations safely in the cloud.\",\n                            \"Share files with coworkers or classmates.\",\n                            \"Collaborate on presentations with multiple people at the same time.\"\n                        ]\n                    }\n                ]\n            },\n            {\n                heading: \"Saving Presentations to OneDrive\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"When you save a presentation, you can choose OneDrive as the storage location. This allows the file to sync automatically with your Microsoft account.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click File → Save As and choose OneDrive instead of saving directly to your computer.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/onedrive/powerpoint_onedrive.png\",\n                        alt: \"Saving a PowerPoint presentation to OneDrive\"\n                    }\n                ]\n            },\n            {\n                heading: \"Opening Files from OneDrive\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Once your presentations are stored in OneDrive, you can open them from any device. Simply sign into PowerPoint and choose OneDrive when opening a file.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can still save files locally to your computer, but OneDrive provides additional convenience and protection.\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Sign in to PowerPoint using a Microsoft account.\",\n                    \"Open the File menu and select Save As.\",\n                    \"Choose OneDrive as the save location.\",\n                    \"Save a presentation to OneDrive.\",\n                    \"Locate your saved presentation inside your OneDrive account.\"\n                ]\n            }\n        ]\n    },\n    {\n        slug: \"creating-and-opening-presentations\",\n        title: \"Creating and Opening Presentations\",\n        description: \"Learn how to create new PowerPoint presentations, use templates, open existing files, pin presentations, and understand Compatibility Mode.\",\n        duration: \"12 min\",\n        videoUrl: \"https://www.youtube.com/embed/OX3vRazm4fw\",\n        practiceFiles: [\n            {\n                name: \"Creating & Opening Presentations Practice File\",\n                url: \"/practice/powerpoint/module-1/creating-opening/Powerpoint_CreatingOpening_Practice.ppt\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Creating a New Presentation\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint files are called presentations. When starting a new project, you will usually begin with a blank presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To create a new presentation, click the File tab to open Backstage view, then select New and choose Blank Presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_file_tab.png\",\n                        alt: \"File tab in PowerPoint\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_backstage.png\",\n                        alt: \"New presentation screen\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Templates\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Templates are predesigned presentations that allow you to quickly start a slideshow with built-in formatting, layouts, and color themes.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"From the New screen in Backstage view, you can search for templates using the search bar or choose from suggested templates.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_new_template.png\",\n                        alt: \"PowerPoint template selection screen\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_review_template.png\",\n                        alt: \"Template preview screen\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_new_template_create.png\",\n                        alt: \"Create presentation from template\"\n                    }\n                ]\n            },\n            {\n                heading: \"Opening Existing Presentations\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You can open presentations that have already been saved on your computer or OneDrive.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click File → Open to view recent files or browse your computer to locate a presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_existing.png\",\n                        alt: \"Open presentations menu\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_existing_browse.png\",\n                        alt: \"Browse option in PowerPoint\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_doc_folder.png\",\n                        alt: \"Open dialog box\"\n                    }\n                ]\n            },\n            {\n                heading: \"Pinning Presentations\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you frequently use the same presentation, you can pin it to the Recent list so it stays easy to access.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Hover your mouse over a recent file and click the pushpin icon to pin the presentation.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_pin_present.png\",\n                        alt: \"Pinned presentation\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_unpin_present.png\",\n                        alt: \"Unpin presentation\"\n                    }\n                ]\n            },\n            {\n                heading: \"Understanding Compatibility Mode\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you open a presentation created in an older version of PowerPoint, it may open in Compatibility Mode.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Compatibility Mode disables certain newer features so the presentation remains compatible with older versions of PowerPoint.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_compatibility.png\",\n                        alt: \"PowerPoint compatibility mode\"\n                    }\n                ]\n            },\n            {\n                heading: \"Converting a Presentation\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"To access newer PowerPoint features, you can convert a presentation from Compatibility Mode to the latest file format.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Open Backstage view, click Convert, and save the presentation as the newer format.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_convert_compat.png\",\n                        alt: \"Convert presentation command\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/creating-opening/create_and_open_save_as.png\",\n                        alt: \"Save converted presentation\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Create a new blank PowerPoint presentation.\",\n                    \"Search for a template and create a presentation from it.\",\n                    \"Open an existing presentation from your computer.\",\n                    \"Pin a presentation in the Recent list.\",\n                    \"Open a presentation in Compatibility Mode.\",\n                    \"Convert the presentation to the latest PowerPoint format.\"\n                ]\n            }\n        ]\n    },\n    {\n        slug: \"saving-presentations\",\n        title: \"Saving Presentations\",\n        description: \"Learn how to save PowerPoint presentations, change file types, export presentations, and recover unsaved work.\",\n        duration: \"10 min\",\n        videoUrl: \"https://www.youtube.com/embed/iwecUGKmiyw\",\n        practiceFiles: [\n            {\n                name: \"PowerPoint Saving Practice File\",\n                url: \"/practice/powerpoint/module-1/saving/Powerpoint_Saving_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Saving a Presentation\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Saving protects your work and allows you to reopen your presentation later. You can save files to your computer or to OneDrive.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Click the File tab to open Backstage view and access the Save and Save As commands.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_file_tab.png\",\n                        alt: \"PowerPoint file tab\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using the Save Command\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Save command stores the current presentation using the same file name and location.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"If the presentation has never been saved before, PowerPoint will automatically open the Save As screen.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_command.png\",\n                        alt: \"Save command in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using Save As\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Save As allows you to create a new version of a presentation or save it to a different location.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"From the Save As screen you can choose to store the presentation on OneDrive, your computer, or another location.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_save_as.png\",\n                        alt: \"Save As screen\"\n                    }\n                ]\n            },\n            {\n                heading: \"Entering a File Name\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"When saving a presentation you must provide a file name. Use descriptive names so you can easily identify presentations later.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_filename_input.png\",\n                        alt: \"File name input field\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_filename_input_change.png\",\n                        alt: \"Changing file name\"\n                    }\n                ]\n            },\n            {\n                heading: \"Choosing a File Type\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint allows you to save presentations in multiple file formats including PowerPoint Presentation (.pptx), PowerPoint Show, or PDF.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_file_type_save_as.png\",\n                        alt: \"File type dropdown\"\n                    }\n                ]\n            },\n            {\n                heading: \"Exporting Presentations\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Export section allows you to convert presentations into different formats such as PDF or video.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_change_file_type.png\",\n                        alt: \"Change file type export screen\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_change_to_pdf.png\",\n                        alt: \"Export presentation as PDF\"\n                    }\n                ]\n            },\n            {\n                heading: \"Sharing Presentations\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If a presentation is stored on OneDrive, you can share it directly with others from within PowerPoint.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can invite people to view or edit the presentation by entering their email address.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_share.png\",\n                        alt: \"Share presentation window\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_share_input.jpeg\",\n                        alt: \"Entering email to share presentation\"\n                    }\n                ]\n            },\n            {\n                heading: \"Recovering Unsaved Presentations\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If PowerPoint closes unexpectedly, you may be able to recover work that was not saved.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Go to File → Info → Manage Presentation and choose Recover Unsaved Presentations.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_recover_unsaved.png\",\n                        alt: \"Recover unsaved presentations\"\n                    }\n                ]\n            },\n            {\n                heading: \"Document Recovery\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"When PowerPoint restarts after a crash, the Document Recovery pane may appear showing versions of your presentation that can be restored.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_doc_recovery.png\",\n                        alt: \"Document recovery pane\"\n                    }\n                ]\n            },\n            {\n                heading: \"PowerPoint Save Options\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint includes settings that control how presentations are saved. You can adjust AutoRecover settings and default save locations.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/saving/saving_options.png\",\n                        alt: \"PowerPoint save options\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Open PowerPoint and create a new blank presentation.\",\n                    \"Save the presentation to your computer using Save As.\",\n                    \"Rename the presentation.\",\n                    \"Export the presentation as a PDF.\",\n                    \"Open the File tab and locate the Recover Unsaved Presentations option.\"\n                ]\n            }\n        ]\n    },\n    {\n        slug: \"slide-basics\",\n        title: \"Slide Basics\",\n        description: \"Learn how to create slides, choose layouts, work with placeholders, duplicate and reorder slides, and apply design changes in PowerPoint.\",\n        duration: \"14 min\",\n        videoUrl: \"https://www.youtube.com/embed/TZfcVbKJs1E\",\n        practiceFiles: [\n            {\n                name: \"PowerPoint Slide Basics Practice File\",\n                url: \"/practice/powerpoint/module-1/slide-basics/Powerpoint_SlideBasics_Practice.pptx\"\n            }\n        ],\n        sections: [\n            {\n                heading: \"Understanding Slides\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint presentations are built one slide at a time. Each slide acts like a page in your presentation, and together the slides tell your full story.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Most slides begin with placeholders. Placeholders are built-in boxes that make it easy to add titles, text, pictures, charts, tables, and other content without having to build the layout yourself.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_slide_placeholders.png\",\n                        alt: \"PowerPoint slide with placeholders\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Using placeholders helps keep slides organized and consistent. Instead of dragging random objects around the screen, PowerPoint gives you a structured starting point.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Using the Slide Navigation Pane\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"The Slide Navigation Pane appears on the left side of the PowerPoint window. It displays thumbnails of every slide in the presentation.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"This pane allows you to jump between slides quickly, see the order of your presentation, and make changes to slide arrangement without leaving the main editing view.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_nav_pane.jpeg\",\n                        alt: \"PowerPoint slide navigation pane\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"When a presentation begins to grow, the Navigation Pane becomes one of the most important tools for staying organized.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Adding a New Slide\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"To continue building a presentation, you will usually need to insert additional slides. PowerPoint makes this easy with the New Slide command on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_new_slide.png\",\n                        alt: \"New Slide command on Home tab\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Clicking the top half of the New Slide button inserts a new slide immediately. This is the fastest way to keep moving when you are building a presentation from scratch.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_quick_slide_add.png\",\n                        alt: \"Quick new slide insertion\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"New slides usually appear directly below the currently selected slide in the Navigation Pane.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Choosing the Right Slide Layout\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Not every slide should look the same. Some slides only need a title, while others may need text, pictures, or two side-by-side content areas.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"That is where slide layouts come in. Layouts control how placeholders are arranged on the slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_choose_slide_layout.png\",\n                        alt: \"Choosing a slide layout\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"One of the most common layouts is Title and Content. It gives you a title placeholder at the top and one large content area below.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_title_and_content.png\",\n                        alt: \"Title and Content layout example\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Choosing the correct layout early makes your slides easier to build and usually saves you from unnecessary resizing later.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing the Layout of an Existing Slide\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Sometimes you create a slide and later realize it needs a different layout. Thankfully, you do not need to start over.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint lets you change the layout of an existing slide using the Layout command on the Home tab.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_change_layout.png\",\n                        alt: \"Changing slide layout from Home tab\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"For example, you may want to switch to a Blank slide if you want full control over where objects appear.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_blank_slide.png\",\n                        alt: \"Blank slide layout option\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Changing layouts is a clean way to reshape a slide without deleting it and rebuilding everything from scratch.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Adding a Text Box\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Placeholders are useful, but sometimes you need more freedom. A text box allows you to place text exactly where you want it on the slide.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To insert one, go to the Insert tab and click Text Box.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_add_text_box.png\",\n                        alt: \"Text Box command on Insert tab\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"After selecting the command, click and drag on the slide to draw the text box area.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_create.png\",\n                        alt: \"Drawing a text box on a slide\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Once the text box appears, you can type directly inside it and format it like any other text in PowerPoint.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_text_box_appear.png\",\n                        alt: \"Text box added to slide\"\n                    }\n                ]\n            },\n            {\n                heading: \"Moving and Resizing Placeholders\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"You are not locked into PowerPoint’s default object positions. Placeholders and text boxes can be moved and resized whenever needed.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To move an object, click its border and drag it to a new location.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_move_placeholder.png\",\n                        alt: \"Moving a placeholder on a slide\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To resize an object, drag one of the sizing handles on the corners or sides. Corner handles adjust both height and width, while side handles adjust only one dimension.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_resize_placeholder.png\",\n                        alt: \"Resizing a placeholder\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"These adjustments help you improve spacing, balance your slide, and make room for other content.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_adjust_placeholder.png\",\n                        alt: \"Adjusted placeholder size and position\"\n                    }\n                ]\n            },\n            {\n                heading: \"Duplicating Slides\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you have a slide with a layout you want to reuse, duplicating it is much faster than rebuilding the entire slide from scratch.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To duplicate a slide, right-click the slide thumbnail in the Navigation Pane and choose Duplicate Slide.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_duplicate_slide.jpeg\",\n                        alt: \"Duplicate Slide command\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can also copy and paste slides. This is useful when moving content between presentations or when you want even more control over placement.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_copy_slide.jpeg\",\n                        alt: \"Copying a slide thumbnail\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_paste_appear.jpeg\",\n                        alt: \"Pasted slide appears in navigation pane\"\n                    }\n                ]\n            },\n            {\n                heading: \"Reordering Slides\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"As your presentation grows, you may decide that some slides belong earlier or later in the sequence.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To reorder slides, click and drag a slide thumbnail in the Navigation Pane. A horizontal insertion line shows where the slide will be placed.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_move_slide.jpeg\",\n                        alt: \"Dragging slide to new position\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Reordering slides is one of the easiest ways to improve the flow of your presentation without changing the content itself.\"\n                    }\n                ]\n            },\n            {\n                heading: \"Applying a Theme\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"Themes give your presentation a consistent visual style by applying coordinated colors, fonts, and background styles across all slides.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"To apply a theme, go to the Design tab and select one of the available theme thumbnails.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_select_theme.png\",\n                        alt: \"Selecting a theme from the Design tab\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Once applied, the theme updates the appearance of your presentation instantly.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_applied_theme.jpeg\",\n                        alt: \"Theme applied to presentation\"\n                    }\n                ]\n            },\n            {\n                heading: \"Formatting the Background\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want to customize the appearance of a slide even more, you can modify the slide background.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Use the Format Background command to choose a solid fill, gradient, texture, or picture background.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_format_background.png\",\n                        alt: \"Format Background command\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"You can then select the background fill style and choose a color or other formatting option.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_background_fill.png\",\n                        alt: \"Background fill options\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"If you want the same background on every slide, click Apply to All.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_format_apply_to_all.jpeg\",\n                        alt: \"Apply background formatting to all slides\"\n                    }\n                ]\n            },\n            {\n                heading: \"Changing Slide Size\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"PowerPoint allows you to choose between Standard (4:3) and Widescreen (16:9) slide sizes.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"Widescreen is the more modern format and is commonly used for classroom projectors, TVs, and online presentations.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_slide_size.png\",\n                        alt: \"Slide size options in PowerPoint\"\n                    }\n                ]\n            },\n            {\n                heading: \"Completed Presentation Example\",\n                blocks: [\n                    {\n                        type: \"paragraph\",\n                        text: \"After adding slides, choosing layouts, inserting text, duplicating content, and applying theme changes, your presentation will start to look polished and organized.\"\n                    },\n                    {\n                        type: \"paragraph\",\n                        text: \"The completed practice file gives a good example of how a simple presentation can become much more visually effective once these slide basics are applied.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png\",\n                        alt: \"Completed PowerPoint presentation example\"\n                    }\n                ]\n            }\n        ],\n        challenge: [\n            {\n                type: \"paragraph\",\n                text: \"Complete the following tasks using the practice presentation:\"\n            },\n            {\n                type: \"list\",\n                ordered: true,\n                items: [\n                    \"Insert a new slide into the presentation.\",\n                    \"Change the layout of one slide.\",\n                    \"Add a text box to a blank slide.\",\n                    \"Move or resize a placeholder.\",\n                    \"Duplicate one of the existing slides.\",\n                    \"Reorder a slide in the Navigation Pane.\",\n                    \"Apply a theme to the presentation.\",\n                    \"Change the background formatting and apply it to all slides.\"\n                ]\n            },\n            {\n                type: \"image\",\n                src: \"/images/powerpoint/module-1/slide-basics/slide-basics_final_result.png\",\n                alt: \"Final result for slide basics challenge\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/content/ms-office/powerpoint/module1Lessons.ts\n");

